using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class ReefDayFour {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Folder="Assets/UnderwaterArt/DayFour";
 public static void Apply(){
  var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Folder);AssetDatabase.Refresh();var old=GameObject.Find("Day 4 wreck encounters");if(old)UnityEngine.Object.DestroyImmediate(old);var root=new GameObject("Day 4 wreck encounters").transform;
  var panel=AssetDatabase.LoadAssetAtPath<Material>("Assets/Ocean/Resources/CreatureFactPanel.mat");if(!panel){panel=new Material(Shader.Find("Sprites/Default"));AssetDatabase.CreateAsset(panel,"Assets/Ocean/Resources/CreatureFactPanel.mat");}
  var wreck=Array.Find(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None),t=>t.name=="Coral colonized timber wreck"&&Mathf.Abs(t.position.z-64)<10);if(!wreck)throw new Exception("Zone 3 wreck missing");
  CreateMoray(root,wreck);CreateGrouper(root);CreateDolphins(root);
  foreach(string name in new[]{"WreckMorayFact","WreckGrouperFact","WreckDolphinFact"}){var importer=AssetImporter.GetAtPath("Assets/Ocean/Resources/"+name+".wav") as AudioImporter;if(!importer)throw new Exception("Missing fact narration "+name);var samples=importer.defaultSampleSettings;samples.loadType=AudioClipLoadType.DecompressOnLoad;samples.compressionFormat=AudioCompressionFormat.PCM;importer.defaultSampleSettings=samples;importer.SaveAndReimport();}
  Physics.SyncTransforms();foreach(var body in root.GetComponentsInChildren<ReefSphereBody>())if(!body.Clear(body.transform.position)&&!body.PlaceNear(body.transform.position))throw new Exception("No clear Day 4 spawn "+body.name);
  EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Validate();Capture();
 }
 static Material Skin(string name,Color color,int kind){string path=Folder+"/"+name+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(!material){material=new Material(Shader.Find("Underwater/Wreck Creature Skin")){enableInstancing=true};AssetDatabase.CreateAsset(material,path);}material.color=color;material.SetFloat("_Kind",kind);EditorUtility.SetDirty(material);return material;}
 static Mesh Save(Mesh mesh,string name){string path=Folder+"/"+name+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved){saved.Clear();saved.indexFormat=mesh.indexFormat;saved.vertices=mesh.vertices;saved.triangles=mesh.triangles;saved.normals=mesh.normals;saved.uv=mesh.uv;saved.colors=mesh.colors;saved.tangents=mesh.tangents;saved.bounds=mesh.bounds;saved.UploadMeshData(false);EditorUtility.SetDirty(saved);UnityEngine.Object.DestroyImmediate(mesh);return saved;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static GameObject Model(string name,Transform parent,Mesh mesh,Material skin){var go=new GameObject(name);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=skin;return go;}
 static void Info(GameObject go,string name,string fact,string audio){var info=go.AddComponent<ReefCreatureInfo>();info.creatureName=name;info.fact=fact;info.narration=Resources.Load<AudioClip>(audio);}
 static WreckCreature Actor(GameObject go,WreckCreature.Species species,float radius){var life=go.AddComponent<SeaLife>();life.kind=species.ToString();life.stationary=true;var body=go.AddComponent<ReefSphereBody>();body.radius=radius;var actor=go.AddComponent<WreckCreature>();actor.species=species;return actor;}
 static void Solid(GameObject go,Vector3 center,float radius,float height){var child=new GameObject("Animal body solid");child.layer=9;child.transform.SetParent(go.transform,false);var capsule=child.AddComponent<CapsuleCollider>();capsule.direction=2;capsule.center=center;capsule.radius=radius;capsule.height=height;}
 static void CreateMoray(Transform parent,Transform wreck){
  var material=Skin("Moray mottled olive",new Color(.3f,.33f,.16f),1);var geometry=new ReefGeometry();var points=new Vector3[25];var radii=new float[25];for(int i=0;i<25;i++){float t=i/24f;points[i]=new Vector3(Mathf.Sin(t*4)*.1f,-.04f*Mathf.Sin(t*Mathf.PI),Mathf.Lerp(-1.65f,.4f,t));radii[i]=Mathf.Lerp(.025f,.13f,t);}geometry.Tube(points,radii,12,Color.white);geometry.Ellipsoid(new Vector3(0,.09f,.48f),new Vector3(.145f,.105f,.29f),12,18);
  var root=Model("Moray in wreck stern opening",parent,Save(geometry.Mesh("Moray body and upper jaw"),"MorayBody"),material);root.transform.position=wreck.TransformPoint(new Vector3(1.2f,1.5f,6.9f));root.transform.rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(wreck.forward,Vector3.up));var actor=Actor(root,WreckCreature.Species.Moray,.22f);root.GetComponent<ReefSphereBody>().centerOffset=new Vector3(0,.06f,.4f);
  var jaw=new GameObject("Hinged lower jaw").transform;jaw.SetParent(root.transform,false);jaw.localPosition=new Vector3(0,.005f,.35f);var lower=new ReefGeometry();lower.Ellipsoid(new Vector3(0,-.025f,.16f),new Vector3(.13f,.037f,.25f),10,16);Model("Lower jaw tissue",jaw,Save(lower.Mesh("Moray lower jaw"),"MorayJaw"),material);actor.jaw=jaw;
  var dark=Skin("Moray mouth and eyes",new Color(.025f,.025f,.018f),1);var mouth=new ReefGeometry();mouth.Ellipsoid(new Vector3(0,.006f,.56f),new Vector3(.11f,.018f,.18f),8,12);mouth.Ellipsoid(new Vector3(-.115f,.115f,.59f),Vector3.one*.021f,8,12);mouth.Ellipsoid(new Vector3(.115f,.115f,.59f),Vector3.one*.021f,8,12);Model("Mouth interior and eyes",root.transform,Save(mouth.Mesh("Moray eyes and mouth"),"MorayDetails"),dark);
  Solid(root,new Vector3(0,0,-.3f),.14f,2.2f);Info(root,"Moray eel","Open mouths help morays breathe.","WreckMorayFact");
 }
 static void CreateGrouper(Transform parent){var source=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/UnderwaterArt/Meshes/PhotographicFishCanonical.asset");if(!source)throw new Exception("Existing fish mesh missing");var mesh=UnityEngine.Object.Instantiate(source);var vertices=mesh.vertices;for(int i=0;i<vertices.Length;i++){vertices[i].x*=1.7f;vertices[i].y*=1.45f;vertices[i].z*=1.2f;}mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateBounds();var material=Skin("Grouper muted spots",new Color(.43f,.4f,.25f),0);material.SetTexture("_MainTex",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/UnderwaterArt/Textures/Fish_albedo.png"));var root=Model("Calm wreck grouper",parent,Save(mesh,"GrouperBody"),material);root.transform.position=new Vector3(-1.8f,-16.6f,63);root.transform.localScale=Vector3.one*1.35f;Actor(root,WreckCreature.Species.Grouper,.95f);Solid(root,Vector3.zero,.22f,1.2f);Info(root,"Grouper","Groupers are ambush predators.","WreckGrouperFact");}
 static float Profile(float z,float[] stations,float[] values){for(int i=0;i<stations.Length-1;i++)if(z<=stations[i+1])return Mathf.Lerp(values[i],values[i+1],Mathf.SmoothStep(0,1,Mathf.InverseLerp(stations[i],stations[i+1],z)));return values[values.Length-1];}
 static Mesh DolphinMesh(){
  var g=new ReefGeometry();float[] zProfile={-1.65f,-1.35f,-1,-.6f,-.1f,.4f,.8f,1.02f,1.16f,1.4f,1.52f};float[] width={.012f,.045f,.09f,.2f,.32f,.34f,.27f,.16f,.095f,.065f,.001f};float[] height={.015f,.04f,.08f,.17f,.27f,.31f,.28f,.2f,.08f,.055f,.001f};float[] centers={0,0,0,0,0,0,.015f,.015f,-.045f,-.05f,-.05f};
  const int rings=96,sides=32;for(int i=0;i<=rings;i++){float t=i/(float)rings,z=Mathf.Lerp(-1.65f,1.52f,t);float w=Profile(z,zProfile,width),h=Profile(z,zProfile,height),cy=Profile(z,zProfile,centers);for(int j=0;j<=sides;j++){float a=j*Mathf.PI*2/sides;g.Vertex(new Vector3(Mathf.Cos(a)*w,cy+Mathf.Sin(a)*h,z),new Vector2(j/(float)sides,t),Color.white);}}
  for(int i=0;i<rings;i++)for(int j=0;j<sides;j++){int a=i*(sides+1)+j;g.Quad(a,a+1,a+sides+2,a+sides+1);}
  Blade(g,new[]{new Vector3(0,.25f,.32f),new Vector3(0,.42f,.07f),new Vector3(0,.62f,-.16f),new Vector3(0,.58f,-.26f),new Vector3(0,.32f,-.3f),new Vector3(0,.25f,-.55f)},.014f);
  for(int side=-1;side<=1;side+=2){Blade(g,new[]{new Vector3(side*.27f,-.08f,.28f),new Vector3(side*.6f,-.16f,-.1f),new Vector3(side*.84f,-.23f,-.46f),new Vector3(side*.65f,-.21f,-.53f),new Vector3(side*.26f,-.13f,-.32f)},.009f);Blade(g,new[]{new Vector3(0,0,-1.24f),new Vector3(side*.35f,.015f,-1.36f),new Vector3(side*.66f,0,-1.58f),new Vector3(side*.6f,-.015f,-1.65f),new Vector3(side*.18f,-.005f,-1.58f),new Vector3(0,0,-1.68f)},.009f);}
  var mesh=g.Mesh("Continuous dolphin profile with swept fins");var b=mesh.bounds;b.Expand(new Vector3(.1f,.5f,.1f));mesh.bounds=b;return mesh;
 }
 static void Blade(ReefGeometry g,Vector3[] outline,float thickness){Vector3 center=Vector3.zero;foreach(var p in outline)center+=p;center/=outline.Length;Vector3 normal=Vector3.Cross(outline[1]-outline[0],outline[2]-outline[0]).normalized*thickness;int top=g.Vertex(center+normal,Vector2.zero,Color.white),bottom=g.Vertex(center-normal,Vector2.zero,Color.white);int first=top+2;foreach(var p in outline){g.Vertex(p+normal,Vector2.zero,Color.white);g.Vertex(p-normal,Vector2.zero,Color.white);}for(int i=0;i<outline.Length;i++){int a=first+i*2,b=first+((i+1)%outline.Length)*2;g.Tri(top,a,b);g.Tri(bottom,b+1,a+1);g.Quad(a,a+1,b+1,b);}}
 static void Fin(ReefGeometry g,Vector3 a,Vector3 b,Vector3 c,float thickness){var normal=Vector3.Cross(b-a,c-a).normalized*thickness;int start=g.Vertex(a+normal,Vector2.zero,Color.white);g.Vertex(b+normal,Vector2.up,Color.white);g.Vertex(c+normal,Vector2.one,Color.white);g.Vertex(a-normal,Vector2.zero,Color.white);g.Vertex(b-normal,Vector2.up,Color.white);g.Vertex(c-normal,Vector2.one,Color.white);g.Tri(start,start+1,start+2);g.Tri(start+5,start+4,start+3);g.Quad(start,start+3,start+4,start+1);g.Quad(start+1,start+4,start+5,start+2);g.Quad(start+2,start+5,start+3,start);}
 static void CreateDolphins(Transform parent){var mesh=Save(DolphinMesh(),"DolphinBody");var material=Skin("Dolphin blue grey",new Color(.35f,.44f,.46f),2);var eyeMaterial=Skin("Dolphin eyes",new Color(.012f,.018f,.022f),2);var eyes=new ReefGeometry();eyes.Ellipsoid(new Vector3(-.19f,.085f,.94f),Vector3.one*.027f,8,12);eyes.Ellipsoid(new Vector3(.19f,.085f,.94f),Vector3.one*.027f,8,12);var eyeMesh=Save(eyes.Mesh("Dolphin eyes"),"DolphinEyes");var center=new Vector3(2,-13.5f,66);
  for(int i=0;i<3;i++){float phase=i*Mathf.PI*2/3;var root=Model("Wreck dolphin "+(i+1),parent,mesh,material);root.transform.position=center+new Vector3(Mathf.Sin(phase)*4.5f,0,Mathf.Cos(phase)*4.5f);root.transform.rotation=Quaternion.LookRotation(new Vector3(Mathf.Cos(phase),0,-Mathf.Sin(phase)));Model("Dolphin eyes",root.transform,eyeMesh,eyeMaterial);var actor=Actor(root,WreckCreature.Species.Dolphin,1.8f);actor.phase=phase;actor.habitatCenter=center;Solid(root,Vector3.zero,.34f,3.2f);Info(root,"Dolphin","Dolphins breathe air at the surface.","WreckDolphinFact");}
 }
 public static void Validate(){
  EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var actors=UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None);if(actors.Length!=5)throw new Exception("Expected moray, grouper and three dolphins");int dolphins=0;
  foreach(var actor in actors){var life=actor.GetComponent<SeaLife>();if(!life||life.danger||life.grabbable||!life.stationary)throw new Exception("Unsafe or duplicate movement owner");actor.Initialize();Vector3 start=actor.transform.position;actor.React();for(int i=0;i<24;i++)actor.Step(1f/30);if(actor.species==WreckCreature.Species.Moray){if(actor.JawAngle<20||Vector3.Distance(start,actor.transform.position)<.05f)throw new Exception("Moray failed mouth/retreat");for(int i=0;i<300;i++)actor.Step(1f/30);if(Vector3.Distance(start,actor.transform.position)>.08f||actor.JawAngle>15)throw new Exception("Moray failed recovery");}
   else {float travel=0;float stalled=0;for(int i=0;i<5400;i++){var before=actor.transform.position;actor.Step(1f/30,actor.species==WreckCreature.Species.Dolphin?(Vector3?)actor.habitatCenter:null);float step=Vector3.Distance(before,actor.transform.position);travel+=step;stalled=step<.0001f?stalled+1f/30:0;if(stalled>8||!actor.GetComponent<ReefSphereBody>().Clear(actor.transform.position))throw new Exception("Stuck/blocked wreck creature "+actor.name);}if(travel<(actor.species==WreckCreature.Species.Dolphin?50:5))throw new Exception("Insufficient creature movement");if(actor.species==WreckCreature.Species.Dolphin)dolphins++;Debug.Log("DAY_FOUR_MOTION "+actor.name+" distance="+travel);}
   var info=actor.GetComponent<ReefCreatureInfo>();int words=(info.creatureName+" "+info.fact).Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries).Length;if(words>=12||!info.narration||info.narration.length>7)throw new Exception("Fact narration too long/missing");
  }
  if(dolphins!=3)throw new Exception("Incomplete dolphin pod");ValidatePodAndStern();ReefNaturalAudio.Validate();Debug.Log("DAY_FOUR_VALIDATED morayMouthRetreatRecovery=passed calmGrouper=passed dolphins=3 factsUnder12Words=passed previousRegressions=passed");
 }
 static void ValidatePodAndStern(){
  EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var pod=Array.FindAll(UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None),a=>a.species==WreckCreature.Species.Dolphin);foreach(var dolphin in pod)dolphin.Initialize();float nearest=float.PositiveInfinity;
  for(int frame=0;frame<3600;frame++){Vector3 diver=pod[0].habitatCenter+new Vector3(Mathf.Sin(frame/300f)*2,-1,Mathf.Cos(frame/300f)*2);if(frame%1200==0)pod[0].React();foreach(var dolphin in pod){dolphin.Step(1f/30,diver);if(!dolphin.GetComponent<ReefSphereBody>().Clear(dolphin.transform.position))throw new Exception("Pod entered wreck/reef");}for(int i=0;i<pod.Length;i++)for(int j=i+1;j<pod.Length;j++)nearest=Mathf.Min(nearest,Vector3.Distance(pod[i].transform.position,pod[j].transform.position));}
  if(nearest<2.5f)throw new Exception("Dolphins crowded each other: "+nearest);
  EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var wreck=Array.Find(UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None),t=>t.name=="Coral colonized timber wreck"&&Mathf.Abs(t.position.z-64)<10);int clear=0;float routeHeight=0;for(float height=2.5f;height<=5;height+=.25f){int count=0;for(int i=0;i<25;i++){var head=wreck.TransformPoint(new Vector3(0,height,Mathf.Lerp(-5.5f,7.5f,i/24f)));if(!Physics.CheckCapsule(head-Vector3.up*.3f,head-Vector3.up*1.25f,.31f,DiverCollisionMotor.DiverSolidMask,QueryTriggerInteraction.Ignore))count++;}if(count==25){clear=count;routeHeight=height;break;}}if(clear<25)throw new Exception("No clear body-sized route through wreck stern");
  var motor=UnityEngine.Object.FindFirstObjectByType<DiverCollisionMotor>();motor.Initialize();var first=wreck.TransformPoint(new Vector3(0,routeHeight,-5.5f));if(!motor.TryTeleport(first-Vector3.up*Camera.main.transform.localPosition.y))throw new Exception("Wreck swim route start blocked");for(int i=1;i<25;i++){var target=wreck.TransformPoint(new Vector3(0,routeHeight,Mathf.Lerp(-5.5f,7.5f,i/24f)));motor.Move(target-Camera.main.transform.position);if(Vector3.Distance(target,Camera.main.transform.position)>.08f)throw new Exception("Diver capsule blocked through wreck stern");}
  Debug.Log("DAY_FOUR_POD_AND_STERN_VALIDATED nearestDolphins="+nearest+" clearCorridorSamples="+clear+"/25 localHeadHeight="+routeHeight);
 }
 public static void Capture(){
  EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory("Renders");var camera=Camera.main;camera.allowHDR=false;camera.fieldOfView=62;var atmosphere=UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>();foreach(var actor in UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None)){
   if(actor.species==WreckCreature.Species.Dolphin&&!actor.name.EndsWith("1"))continue;actor.Initialize();if(actor.species==WreckCreature.Species.Moray){actor.React();for(int i=0;i<24;i++)actor.Step(1f/30);}camera.transform.position=actor.transform.position+actor.transform.forward*(actor.species==WreckCreature.Species.Moray?2:3.2f)+actor.transform.right*1.4f+Vector3.up*.5f;camera.transform.LookAt(actor.transform.position);atmosphere.Apply(camera);actor.GetComponent<ReefCreatureInfo>().Preview(camera.transform);ReefCorrectionAudit.Capture(camera,"Renders/Day_Four_"+actor.species+".png");
  }
 }
}
}
